import{c as t,Q as s,j as r,m as a}from"./chunks/framework.BqPkuuVc.js";const u=JSON.parse('{"title":"Leaderboard","description":"","frontmatter":{},"headers":[],"relativePath":"user/screens/leaderboard.md","filePath":"user/screens/leaderboard.md"}'),n={name:"user/screens/leaderboard.md"};function o(i,e,h,d,l,c){return s(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="leaderboard" tabindex="-1">Leaderboard <a class="header-anchor" href="#leaderboard" aria-label="Permalink to &quot;Leaderboard&quot;">​</a></h1><p><strong>Audience:</strong> Timing operators, organisers and commentators following the results live from inside Manager.</p><p>The <strong>Leaderboard</strong> page is Manager&#39;s own live results board: every class in the event, one table each, updating as radio punches arrive, cards are read and statuses change. Nothing needs refreshing. It&#39;s the same board the arena TVs show, but laid out for somebody reading it at a desk — and it lives inside Manager rather than on a display of its own.</p><h2 id="opening-the-leaderboard" tabindex="-1">Opening the Leaderboard <a class="header-anchor" href="#opening-the-leaderboard" aria-label="Permalink to &quot;Opening the Leaderboard&quot;">​</a></h2><p>Open the event and choose <strong>Leaderboard</strong> under <strong>Event live</strong> in the navigation. The <strong>Event live</strong> group appears once the event has been started, so the page is there in <strong>Live</strong> and <strong>Archive</strong> mode but not in <strong>Setup</strong>.</p><p>The page sits inside Manager, so it&#39;s protected by the <a href="./../reference/settings#access-protection">access PIN</a> like every other manager page. It follows your own Manager theme and language rather than a screen&#39;s.</p><blockquote><p><strong>Tip:</strong> To keep the board up on a second monitor while you work, open the page in its own browser window and drag it across. Every view in Manager is a web page, so a second window stays live alongside the first.</p></blockquote><h2 id="which-classes-it-shows" tabindex="-1">Which classes it shows <a class="header-anchor" href="#which-classes-it-shows" aria-label="Permalink to &quot;Which classes it shows&quot;">​</a></h2><p>The page shows <strong>every class in the event</strong> — you don&#39;t choose them. A class added during the event appears on its own. A class with nobody entered in it is left off until somebody is.</p><p>Classes are laid out across the columns in a fixed order: by category (Elite, A, AS, Sport, B, N), then by age group, then by name. If even one <strong>relay class</strong> is on the board, the whole board drops to a <strong>single column</strong>, because a relay row is too wide to sit beside another class.</p><blockquote><p><strong>Note:</strong> To show only some classes, or to lay them out in your own order, use a <a href="./creating-screens">screen</a> instead and open it in a browser window. Each screen has its own class list; this page doesn&#39;t.</p></blockquote><h2 id="what-a-class-table-shows" tabindex="-1">What a class table shows <a class="header-anchor" href="#what-a-class-table-shows" aria-label="Permalink to &quot;What a class table shows&quot;">​</a></h2><p>Each class is a table headed by the class name. Runners are in the order Manager ranks them: finishers fastest first, then runners on course, then those who didn&#39;t finish, with the people Manager knows nothing about yet at the bottom. The full rules are in <a href="./../reference/status-and-race-time#how-results-are-ordered">How results are ordered</a>.</p><table tabindex="0"><thead><tr><th>Column</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Place</strong> (unlabelled, on the left)</td><td>The finishing place, for runners with an <strong>OK</strong> result. <strong>1</strong>, <strong>2</strong> and <strong>3</strong> are coloured gold, silver and bronze once the result is final.</td></tr><tr><td><strong>Name</strong></td><td>The competitor&#39;s name, with their club badge when <strong>Show club icon</strong> is on. With <strong>Competitor time display</strong> set to <strong>Both</strong>, the club name sits on a second line under the name.</td></tr><tr><td><strong>Club</strong></td><td>The club, when <strong>Club display</strong> isn&#39;t <strong>Hide</strong> and the time display isn&#39;t <strong>Both</strong>. <strong>Abbreviations</strong> shows the first four characters of the club&#39;s short name.</td></tr><tr><td><strong>Start</strong></td><td>The start time, or <code>--:--</code> when there isn&#39;t one. Hidden when <strong>Show start time</strong> is off.</td></tr><tr><td>One column per <strong>radio control</strong></td><td>The runner&#39;s split at that control. See <a href="#radio-control-columns">Radio-control columns</a>.</td></tr><tr><td><strong>Penalty</strong> and <strong>Points</strong></td><td>Only for a score course: the points collected and any penalty for being over time. See <a href="#score-courses">Score courses</a>.</td></tr><tr><td><strong>Finish</strong></td><td>The race time for a finisher, a ticking running time for somebody on course, or the status for anyone else.</td></tr></tbody></table><h3 id="the-finish-column" tabindex="-1">The Finish column <a class="header-anchor" href="#the-finish-column" aria-label="Permalink to &quot;The Finish column&quot;">​</a></h3><p>What&#39;s in the <strong>Finish</strong> cell depends on where the runner is:</p><ul><li><strong>Finished (OK)</strong> — their race time, and underneath it how far behind the leader they are. The time display setting decides which of the two you see. The leader&#39;s time is always shown.</li><li><strong>On course</strong> — their <strong>running time</strong>, counting up every second on a tinted row. It&#39;s timed from their start against the event clock, so it is what their race time would be if they finished now. With <strong>Show projected times</strong> on, a runner who has passed a radio control also shows <strong>Predicted:</strong> and the finish time Manager expects from their splits so far.</li><li><strong>On course, but no running time yet</strong> — <strong>On course</strong> shows in place of a time when Manager has no start time to count from, or when their start time hasn&#39;t come round yet.</li><li><strong>Not started yet</strong> — the cell is blank until their start time. When it passes, Manager moves them to On course and the clock starts.</li><li><strong>A status</strong> — <strong>DNS</strong>, <strong>DNF</strong>, <strong>MP</strong>, <strong>DSQ</strong>, <strong>OVT</strong>, <strong>OOC</strong>, <strong>NT</strong>, <strong>NP</strong> or <strong>CAN</strong>, shown as a coloured chip. See <a href="./../reference/status-and-race-time#the-status-values">The status values</a>.</li><li><strong>No time at all</strong> — <code>--:--</code>.</li></ul><p>Running times carry on past midnight for a night event, and follow the replay speed during a replay. See <a href="./../reference/status-and-race-time#races-that-cross-midnight">Races that cross midnight</a>.</p><h3 id="provisional-results" tabindex="-1">Provisional results <a class="header-anchor" href="#provisional-results" aria-label="Permalink to &quot;Provisional results&quot;">​</a></h3><p>A runner who has a radio finish punch but hasn&#39;t had their card read yet has a <strong>provisional OK</strong>. On the Leaderboard the row is tinted and set in italics, and the place gets <strong>no medal colour</strong> until the card is read. A provisional status, such as an MP from a radio finish, carries a <code>*</code> on its chip. See <a href="./../reference/status-and-race-time#provisional-vs-final-ok">Provisional vs final OK</a>.</p><h3 id="checked-in-runners" tabindex="-1">Checked-in runners <a class="header-anchor" href="#checked-in-runners" aria-label="Permalink to &quot;Checked-in runners&quot;">​</a></h3><p>Reaching the <strong>check</strong> isn&#39;t starting, so a runner who has only checked in isn&#39;t shown as on course here. Their row stays as not yet started until their start time passes or a start punch arrives. See <a href="./../running-the-event/safety-check">Safety check</a>.</p><h3 id="sub-second-timing" tabindex="-1">Sub-second timing <a class="header-anchor" href="#sub-second-timing" aria-label="Permalink to &quot;Sub-second timing&quot;">​</a></h3><p>With <strong>Use sub-second timing</strong> turned on for the event, <strong>race times</strong> in the <strong>Finish</strong> column show hundredths (<code>30:00.23</code>). That&#39;s the only thing on the board that shows a fraction. Radio splits, behind times, running times and predicted times stay in whole seconds, even though places and split ranks are decided on the fractions. Left off (the default), a whole second is the finest difference the board will separate two runners by. See the setting under <a href="./../event-setup/create-event#details">Editing event details → Details</a>.</p><h2 id="radio-control-columns" tabindex="-1">Radio-control columns <a class="header-anchor" href="#radio-control-columns" aria-label="Permalink to &quot;Radio-control columns&quot;">​</a></h2><p>Each radio control on the class&#39;s course gets a column, headed by the control&#39;s <strong>Radio Name</strong> (or its code). For each runner who has passed it, the cell shows:</p><ul><li>their split time at that control,</li><li>how far behind the fastest split there they are,</li><li>their rank at that control, shaded green for the fastest three.</li></ul><p>The time display setting decides whether you see the split, the behind time, or both. A blank cell means no punch from that runner at that control yet.</p><p>How many radio columns a class gets is set by <strong>Max radios</strong> (4 unless you change it). When a class has more radio controls than that, the priority you give each one on the <strong>Classes</strong> page decides which win the space: <strong>High</strong> first, then <strong>Medium</strong>, then <strong>Low</strong>, then those with no priority. Controls set to <strong>Hide</strong> never show. See <a href="./../event-setup/controls-and-radio-controls#marking-radio-controls-and-setting-their-priority">Marking radio controls and setting their priority</a>.</p><h2 id="score-courses" tabindex="-1">Score courses <a class="header-anchor" href="#score-courses" aria-label="Permalink to &quot;Score courses&quot;">​</a></h2><p>On a <strong>score</strong> or <strong>scatter</strong> course, runners choose their own controls in their own order, so nobody runs the same leg as anybody else. A class on such a course shows <strong>no radio columns</strong>.</p><p>A score class adds a <strong>Points</strong> column just before <strong>Finish</strong>: the points scored, shown once the result is final. It shows <code>0</code> for a finisher who collected nothing, because that is their result. A <strong>Penalty</strong> column appears beside it only when somebody in the class lost points for being over time. A runner with no penalty shows a blank there.</p><p>A class whose competitors do <strong>every course</strong> in turn, such as a Duo class, has one row per competitor with their overall result. There are no per-course columns yet. A class whose courses are all score courses shows no radio columns. Otherwise the radio columns come from the first course only. See <a href="./../event-setup/classes-and-courses#classes-whose-competitors-do-every-course">Classes whose competitors do every course</a>.</p><h2 id="relay-classes" tabindex="-1">Relay classes <a class="header-anchor" href="#relay-classes" aria-label="Permalink to &quot;Relay classes&quot;">​</a></h2><p>A relay class is drawn as a different table, one row per <strong>team</strong>:</p><table tabindex="0"><thead><tr><th>Column</th><th>What it shows</th></tr></thead><tbody><tr><td><strong>Place</strong></td><td>The team&#39;s place, with medal colours once the result is final.</td></tr><tr><td>Team name</td><td>The team, with its club underneath unless <strong>Club display</strong> is <strong>Hide</strong>.</td></tr><tr><td><strong>Team</strong></td><td>The runners, one per line in leg order, with the club badge beside them. With <strong>Show relay team members on single line</strong> turned on, they&#39;re compressed onto one line.</td></tr><tr><td><strong>Start</strong></td><td>The team&#39;s start time.</td></tr><tr><td><strong>Leg 1 …</strong>, <strong>Leg 2 …</strong></td><td>Each leg&#39;s radio controls, headed with the leg number and the control. A relay shows at most <strong>two</strong> radio controls per leg, whatever <strong>Max radios</strong> says, or fewer if <strong>Max radios</strong> is lower.</td></tr><tr><td><strong>Leg 1 finish</strong>, <strong>Leg 2 finish</strong> …</td><td>The team&#39;s time at the end of that leg, from the mass start. Under it is the runner&#39;s own leg time, and the team&#39;s behind time. If a leg went wrong, the runner&#39;s status replaces the leg time, so you can see which runner cost the team its result.</td></tr><tr><td><strong>Time</strong></td><td>The team&#39;s total time, or the team&#39;s status.</td></tr></tbody></table><p>Teams are compared only at the radio controls their courses really share, so forked legs still compare fairly. See <a href="./../event-setup/relay-events#radio-controls-per-leg">Relay events</a> for how relay results and leg times are worked out.</p><h2 id="results-quarantine" tabindex="-1">Results quarantine <a class="header-anchor" href="#results-quarantine" aria-label="Permalink to &quot;Results quarantine&quot;">​</a></h2><p>A class held back by the <a href="./../event-setup/results-quarantine">results quarantine</a> is shown <strong>in full</strong> on this page, because it is part of Manager. The arena screens, the spectator app and the kiosk show the quarantine notice in its place until the class is released.</p><h2 id="changing-the-layout" tabindex="-1">Changing the layout <a class="header-anchor" href="#changing-the-layout" aria-label="Permalink to &quot;Changing the layout&quot;">​</a></h2><p>Click the <strong>gear</strong> icon at the right of the board&#39;s header to open the settings. If you&#39;ve turned the header off, the gear sits by itself above the board instead.</p><p>The settings are the same Leaderboard settings an arena screen has — <strong>Font size</strong>, <strong>Columns</strong>, <strong>Name column width</strong>, <strong>Club display</strong>, <strong>Competitor time display</strong>, <strong>Max places per class</strong>, <strong>Max radios</strong>, <strong>Auto-scroll</strong>, the header, and the switches for club icons, relay team members, projected times, start times and class names. What each one does is in the settings table on <a href="./creating-screens#choosing-what-a-screen-shows">Creating screens</a>. <strong>Apply</strong> saves and keeps the dialog open; <strong>Save</strong> saves and closes.</p><p>Some settings are left out because they belong to a display device: <strong>Shows</strong>, <strong>Theme</strong>, <strong>Language</strong>, the <strong>Snapshot</strong> tab and <strong>Delete</strong>. This page always shows the Leaderboard, in your own theme and language.</p><p>A few of the starting values differ from an arena screen&#39;s, because one person reads this board up close rather than a crowd from across the arena:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Starts at on this page</th></tr></thead><tbody><tr><td><strong>Auto-scroll</strong></td><td>Off — a board that moves while you&#39;re reading it is no help at a desk</td></tr><tr><td><strong>Club display</strong></td><td><strong>Hide</strong>, to give the width to the results</td></tr><tr><td><strong>Show class names in header</strong></td><td>Off — the board carries every class, so the header shows the event name instead</td></tr></tbody></table><p>All of them are yours to change. The settings are kept with the event and apply to whoever opens this page for that event. They are stored as the event&#39;s <strong>manager</strong> screen, which is also listed on the <strong>Screens</strong> page and can be configured from its gear icon there. Changing them never affects an arena TV, including the <strong>all</strong> screen.</p><h3 id="max-places-per-class" tabindex="-1">Max places per class <a class="header-anchor" href="#max-places-per-class" aria-label="Permalink to &quot;Max places per class&quot;">​</a></h3><p><strong>Max places per class</strong> set to a number (top 3 to top 10) shows only that many finishers per class and hides everyone else, including runners still on course. A line under the table says how many are in the class: <strong>Current top 3 (12 total)</strong> while the places can still change, and <strong>Top 3 (12 total)</strong> once they&#39;re settled.</p><h3 id="the-header" tabindex="-1">The header <a class="header-anchor" href="#the-header" aria-label="Permalink to &quot;The header&quot;">​</a></h3><p>With the header on, the top of the board shows the meshO logo, the event name, the event clock and the gear. It stays at the top as you scroll. Turning <strong>Show class names in header</strong> on puts every class name there instead of the event name.</p><h2 id="the-leaderboard-page-arena-screens-and-commentary" tabindex="-1">The Leaderboard page, arena screens and Commentary <a class="header-anchor" href="#the-leaderboard-page-arena-screens-and-commentary" aria-label="Permalink to &quot;The Leaderboard page, arena screens and Commentary&quot;">​</a></h2><p>The three show the same live results, for different people:</p><table tabindex="0"><thead><tr><th></th><th><strong>Leaderboard page</strong></th><th><strong>Arena screens</strong></th><th><strong>Commentary</strong></th></tr></thead><tbody><tr><td>Who it&#39;s for</td><td>You, at a computer running Manager</td><td>The crowd, on a TV with nobody at it</td><td>The announcer</td></tr><tr><td>Where it opens</td><td><strong>Event live → Leaderboard</strong> in Manager</td><td>Its own address, <code>/screen/&lt;screen-id&gt;</code></td><td><strong>Screens → Commentary → Open</strong></td></tr><tr><td>Classes</td><td>Every class, always</td><td>The classes you choose for that screen</td><td>Every class, with filters</td></tr><tr><td>Layout settings</td><td>The gear on the page</td><td>The gear on the <strong>Screens</strong> page</td><td>Its own filters and panels</td></tr><tr><td>Theme and language</td><td>Yours</td><td>The screen&#39;s own</td><td>Commentary&#39;s own</td></tr><tr><td>Quarantined classes</td><td>Shown in full</td><td>Notice shown instead</td><td>Shown in full</td></tr><tr><td>Reported on the <strong>Screens</strong> page</td><td>No device behind it — no health, snapshot or reload</td><td>Last heard from, FPS, disconnects, snapshot, reload</td><td>Listed while open</td></tr></tbody></table><p>An arena screen can also show other things — start times, a Live top 10 wall, analysis graphs. See <a href="./creating-screens">Creating screens</a> and <a href="./tv-screens">TV screens</a>. Commentary tells the same results as a feed of events, and clicking a class name there opens that class&#39;s Leaderboard table. See <a href="./commentary">Commentary</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./creating-screens">Creating screens</a> — arena screens, and every Leaderboard setting explained</li><li><a href="./tv-screens">TV screens</a> — a bank of arena TVs set up and changed together</li><li><a href="./commentary">Commentary</a> — the announcer&#39;s live feed</li><li><a href="./../event-setup/controls-and-radio-controls">Controls and radio controls</a> — which radio controls get a column</li><li><a href="./../reference/status-and-race-time">Status and race time rules</a> — statuses, provisional results and the result order</li><li><a href="./../after-the-event/results">Results</a> — the official results, for publishing and exporting</li><li><a href="./../event-setup/results-quarantine">Results quarantine</a> — holding elite results back from the public screens</li></ul>',56)])])}const p=t(n,[["render",o]]);export{u as __pageData,p as default};
